import sys; sys.path.insert(0,'/tmp/ss-build/tools/c5_gaps')
from lib import *
M='maths'
# ---------- 1 kg and g ----------
build(M,'weight-and-capacity','kilograms-and-grams',"Kilograms and grams: reading scales, converting, comparing",
 "Anu's list of weights",
 "Anu wrote the weight of things in her house: iron almirah 40 g, bed 60 kg, rice bag 5 kg, refrigerator 50 g. Something is wrong - can a whole almirah weigh as little as a few coins? Let us learn to measure and judge weights like a shopkeeper.",
 [("We measure weight in grams (g) and kilograms (kg). 1 kg = 1,000 g. Small things like a water bottle's contents or a pencil are weighed in grams; big things like a rice bag, a bed or an almirah in kilograms.","1 kg = 1,000 g"),
  ("Check Anu's list by common sense: an iron almirah is about 40 kg (not 40 g), a refrigerator about 50 kg (not 50 g), a bed 60 kg, a rice bag 5 kg, and a water bottle 650 g is right.","sensible units"),
  ("To read a weighing scale, first look at what one small mark stands for. If 1 kg is divided into 4 parts, each mark is 250 g. If it has 2 parts, each mark is 500 g. The pointer at the first mark after 2 kg reads 2 kg 250 g.","read the scale"),
  ("Two scales may show the same bag differently: one in kg and another in g. A bag of 2 kg shows 2,000 g on the other scale. A double number line helps: every kg step on top matches 1,000 g below, so we multiply by 1,000.","double number line"),
  ("To change kg and g to grams: 3 kg 500 g = 3,000 g + 500 g = 3,500 g. Shrenu's kitchen scale shows only grams, so for 2 kg 250 g of flour it must show 2,250 g.","3 kg 500 g = 3,500 g"),
  ("Be careful with the zeros. 5 kg 50 g = 5,000 g + 50 g = 5,050 g, not 5,500 g. Shamim was right and Rehan was wrong, because 50 g is much less than 500 g.","5 kg 50 g = 5,050 g"),
  ("To change grams back, split at the thousands: 10,760 g = 10 kg 760 g, 4,080 g = 4 kg 80 g and 12,042 g = 12 kg 42 g.","grams to kg"),
  ("To compare, bring both weights to the same unit. 1 kg 600 g = 1,600 g, which is less than 1,700 g. And 1 kg 600 g is more than 1 kg 60 g, because 600 g is more than 60 g.","compare in grams"),
  ("Picnic fruits: watermelon 3 kg, pineapple 1 kg 750 g, apples 1 kg 250 g, mangoes 2 kg. In descending order: watermelon, mangoes, pineapple, apples. Watermelon is the heaviest and apples the lightest.","descending order")],
 ("Convert 8 kg 69 g to grams and say which is heavier: 8 kg 69 g or 8,609 g.",[("8 kg = 8,000 g, so 8 kg 69 g = 8,000 + 69 = 8,069 g.","Place the 69 in the last two places of the grams part, using a 0 as a placeholder."),("Compare 8,069 g with 8,609 g: 8,609 is greater.","Compare thousands first, then hundreds: 8,0.. is smaller than 8,6..")]),
 ("Explain to a friend how to change 4 kg 80 g into grams and why it is not 4,800 g.",["1 kg = 1,000 g","4 kg = 4,000 g, add 80 g to get 4,080 g","80 g is a small number, so it needs a 0 before it"],["Writing 4,800 g by putting 80 next to 4 as 800"]),
 ["1 kg = 1,000 g and 1 g is a very small weight.","kg to g: multiply by 1,000; for kg and g together add the grams afterwards.","g to kg: 12,042 g = 12 kg 42 g.","Compare weights after bringing them to the same unit.","Use common sense: big things in kg, small things in g."],
 [mcq("r1-kg1",1,"Which weight is sensible for a refrigerator?","50 kg",[("50 g","50 g is about the weight of a lemon - far too small for a refrigerator."),("5 g","5 g is lighter than a coin.")],"A refrigerator is a heavy machine, so its weight is in kilograms."),
  num("r1-kg2",1,"3 kg 500 g = ___ g",3500,"3 kg = 3,000 g, plus 500 g gives 3,500 g.",[(3050,"500 g needs three digits: 3,000 + 500 = 3,500.")]),
  num("r1-kg3",1,"How many grams are there in 2 kg 250 g?",2250,"2 kg = 2,000 g and 2,000 + 250 = 2,250 g.",[(2025,"250 g must be added fully, not as 25.")]),
  tf("r1-kg4",1,"A water bottle weighing 650 g is a sensible weight.",True,"650 g is a little over half a kilogram, which matches a bottle of water."),
  num("r2-kg5",2,"5 kg 50 g = ___ g",5050,"5 kg = 5,000 g; add 50 g to get 5,050 g. Rehan's 5,500 g is wrong because it adds 500 g.",[(5500,"That is 5 kg 500 g, not 5 kg 50 g.")]),
  mcq("r2-kg6",2,"10,760 g is the same as",'10 kg 760 g',[("1 kg 760 g","10,000 g is 10 kg, not 1 kg."),("107 kg 60 g","Split at the thousands: 10 | 760.")],"10,760 g = 10,000 g + 760 g = 10 kg 760 g."),
  mcq("r2-kg7",2,"Which sign makes this true? 1 kg 600 g __ 1,700 g","<",[(">","1 kg 600 g is 1,600 g, which is smaller."),("=","1,600 is not 1,700.")],"1,600 g is less than 1,700 g."),
  short("r2-kg8",2,"4,080 g = ___ kg ___ g (write like 4 kg 80 g)",["4 kg 80 g","4kg 80g","4 kg 80"],"4,080 g = 4,000 g + 80 g = 4 kg 80 g.",[("4 kg 800 g","80 is 80 g, not 800 g.")]),
  short("r3-kg9",3,"Which fruit among watermelon 3 kg, pineapple 1 kg 750 g, apples 1 kg 250 g and mangoes 2 kg weighs the least?",["apples","apple"],"1 kg 250 g = 1,250 g is the smallest weight.",[("pineapple","1,750 g is more than 1,250 g.")]),
  mcq("r3-kg10",3,"Each small mark on a scale between 0 and 1 kg is 250 g. A pointer at the 3rd mark shows",'750 g',[("300 g","Each mark is 250 g, so count 250, 500, 750."),("350 g","Count the marks: 250 + 250 + 250.")],"3 marks x 250 g = 750 g."),
  tf("r3-kg11",3,"900 g + 7,000 g is equal to 7 kg + 900 g.",True,"Both are 7,900 g."),
  num("r3-kg12",3,"Convert 12,042 g into kg and g. How many grams are left over after taking out the kilograms?",42,"12,042 g = 12 kg 42 g, so 42 g remain.",[(420,"Write the 0 and read 042 as 42 g.")])],
 svg=("c5-kg-g-double-line.svg","Double number line showing kilograms above and grams below","1 kg = 1,000 g: each step up one kg is 1,000 g"))

# ---------- 2 litres and ml ----------
build(M,'weight-and-capacity','litres-and-millilitres',"Capacity: litres and millilitres",
 "At the petrol pump",
 "Sam bought 2 l 500 ml of petrol and Tina bought 2 l 800 ml. Together how much petrol did they buy, and who bought more? A milkman also pours milk in bottles of different sizes. Let us learn how to measure how much a container holds.",
 [("Capacity is how much a container can hold. We measure liquids in litres (l) and millilitres (ml). 1 l = 1,000 ml.","1 l = 1,000 ml"),
  ("A spoon holds a few millilitres, a small bottle 200 ml or 500 ml, a big cold-drink bottle 1 l or 2 l, a bucket about 10 l and a water tank thousands of litres.","containers"),
  ("Look at a measuring jug. The scale shows 250 ml, 500 ml, 750 ml and 1 l. The water at the line for 500 ml is half a litre.","measuring jug"),
  ("Change litres and millilitres to millilitres like weights: 1 l 400 ml = 1,000 ml + 400 ml = 1,400 ml. But 1,040 ml is only 1 l 40 ml. So 1 l 400 ml is more than 1,040 ml.","1 l 400 ml = 1,400 ml"),
  ("Changing the other way: 3,250 ml = 3 l 250 ml. Split the number after the thousands place, just as with grams.","ml to l"),
  ("To add, add the same units: 2 l 500 ml + 2 l 800 ml. Litres: 2 + 2 = 4 l. Millilitres: 500 + 800 = 1,300 ml = 1 l 300 ml. Total 4 l + 1 l 300 ml = 5 l 300 ml. So Tina bought 300 ml more than Sam.","add litres and ml"),
  ("To subtract, you may need to regroup. 5 l - 1 l 300 ml: write 5 l as 4 l 1,000 ml. Then 4 l - 1 l = 3 l and 1,000 ml - 300 ml = 700 ml. Answer 3 l 700 ml.","regroup 1 l"),
  ("Compare capacities only after changing them to the same unit. 2 l 500 ml = 2,500 ml; 2,050 ml is less than that.","same unit")],
 ("A tank has 5 l of water. 1 l 300 ml is used for cooking. How much water is left?",[("Write 5 l as 4 l 1,000 ml.","We cannot take 300 ml from 0 ml, so we borrow 1 l = 1,000 ml."),("Subtract: 4 l - 1 l = 3 l and 1,000 ml - 300 ml = 700 ml. Left: 3 l 700 ml.","Check: 3 l 700 ml + 1 l 300 ml = 5 l.")]),
 ("How would you tell your friend which is more: 1 l 400 ml or 1,040 ml?",["Convert both to millilitres","1 l 400 ml = 1,400 ml","1,400 ml is more than 1,040 ml"],["Thinking 1,040 ml is bigger because it has more digits"]),
 ["Capacity is measured in litres and millilitres; 1 l = 1,000 ml.","l and ml to ml: 2 l 250 ml = 2,250 ml.","Add or subtract the same units; regroup 1 l as 1,000 ml when needed.","Compare after converting to the same unit."],
 [mcq("r1-cp1",1,"Which container is most likely to hold about 5 ml?","a spoon",[("a bucket","A bucket holds around 10 l."),("a water tank","A tank holds thousands of litres.")],"A spoon holds only a few millilitres."),
  num("r1-cp2",1,"How many ml are there in 1 litre?",1000,"1 l = 1,000 ml.",[(100,"That is a hundred; one litre is ten hundreds.")]),
  num("r1-cp3",1,"2 l 250 ml = ___ ml",2250,"2 l = 2,000 ml and 2,000 + 250 = 2,250 ml.",[(2025,"Add the full 250 ml.")]),
  tf("r1-cp4",1,"1 l 400 ml is the same as 1,040 ml.",False,"1 l 400 ml = 1,400 ml; 1,040 ml is 1 l 40 ml."),
  num("r2-cp5",2,"2 l 500 ml + 2 l 800 ml = ? Give the answer in ml.",5300,"4 l + 1,300 ml = 5 l 300 ml = 5,300 ml.",[(4300,"500 + 800 = 1,300 ml gives another litre.")]),
  mcq("r2-cp6",2,"Sam bought 2 l 500 ml and Tina 2 l 800 ml petrol. Tina bought more by",'300 ml',[("200 ml","2,800 - 2,500 = 300 ml."),("1 l","The litres are the same, 2 l each.")],"2 l 800 ml - 2 l 500 ml = 300 ml."),
  short("r2-cp7",2,"5 l - 1 l 300 ml = ? (write like 3 l 700 ml)",["3 l 700 ml","3l 700ml","3 l 700"],"Borrow 1 l: 4 l 1,000 ml - 1 l 300 ml = 3 l 700 ml.",[("4 l 700 ml","Remember you borrowed one litre, leaving 4 l before subtracting.")]),
  mcq("r2-cp8",2,"3,250 ml is",'3 l 250 ml',[("32 l 50 ml","Split after the thousands place."),("3 l 25 ml","250 ml is 250, not 25.")],"3,250 = 3,000 + 250."),
  tf("r3-cp9",3,"2,050 ml is more than 2 l 500 ml.",False,"2 l 500 ml = 2,500 ml, which is more than 2,050 ml."),
  num("r3-cp10",3,"A milkman fills 4 bottles of 500 ml each. How many litres of milk is that?",2,"4 x 500 = 2,000 ml = 2 l.",[(20,"2,000 ml is 2 l, not 20 l.")]),
  mcq("r3-cp11",3,"Which unit is best for the amount of juice in a small packet?","ml",[("kg","kg measures weight, not liquid."),("km","km measures distance.")],"Small drinks are measured in millilitres."),
  num("r3-cp12",3,"How many 250 ml glasses can be filled from 1 litre?",4,"1,000 / 250 = 4.",[(2,"Two glasses would be 500 ml only.")])],
 svg=("c5-capacity-jug.svg","A measuring jug showing 250, 500, 750 ml and 1 litre marks","1 litre = 1,000 millilitres"))

# ---------- 3 problems ----------
build(M,'weight-and-capacity','weight-and-capacity-problems',"Milligrams, quintals, tonnes and word problems",
 "How much can an ant carry?",
 "An ant weighs only 1 to 5 milligrams, yet it carries things much heavier than itself! A gold ornament is measured in milligrams, while a truck of rice is measured in tonnes. Today we learn the very small and the very big units, and solve shopping problems.",
 [("For very light things we use the milligram (mg): 1 g = 1,000 mg. Medicine ingredients and gold ornaments are measured this way. A sugar sachet of 5 g is 5,000 mg.","1 g = 1,000 mg"),
  ("Converting g to mg is like kg to g. 4 g 100 mg = 4,000 mg + 100 mg = 4,100 mg, and 10 g 500 mg = 10,500 mg.","g to mg"),
  ("For very heavy things: 100 kg = 1 quintal and 10 quintals = 1 tonne = 1,000 kg. So 5,000 kg = 50 quintals = 5 tonnes, and 9,000 kg = 90 quintals = 9 tonnes. The whole ladder is: 1,000 mg = 1 g, 1,000 g = 1 kg, 100 kg = 1 quintal, 10 quintals = 1 tonne.","unit ladder"),
  ("The King's weight puzzle: on his birthday the king donates wheat equal to 10 times his weight. If he gives 800 kg, his weight is 800 / 10 = 80 kg. Last year he gave 780 kg, so he weighed 78 kg. He gained 80 - 78 = 2 kg in a year.","10 times"),
  ("Adding weights: Rathna bought 2 kg 500 g and 1 kg 750 g of rice. Add kg: 2 + 1 = 3 kg. Add g: 500 + 750 = 1,250 g = 1 kg 250 g. Total 4 kg 250 g.","2 kg 500 g + 1 kg 750 g"),
  ("Another way: change to grams. 2,500 g + 1,750 g = 4,250 g = 4 kg 250 g. Both methods give the same answer, so pick the one you like.","grams method"),
  ("Subtracting weights: how much extra rice did she buy for the household than for Pongal? 2 kg 500 g - 1 kg 750 g = 2,500 g - 1,750 g = 750 g.","subtract"),
  ("We can add and subtract only like quantities: kg with kg, g with g, mg with mg. If you cannot subtract the small units, regroup one bigger unit into the smaller one.","like quantities")],
 ("Rathna bought 2 kg 500 g rice and 1 kg 750 g rice. Find the total and how much more the first lot is.",[("Total: 2,500 g + 1,750 g = 4,250 g = 4 kg 250 g.","Change both to grams, add, then change back to kg and g."),("Difference: 2,500 g - 1,750 g = 750 g.","Subtract the smaller weight from the bigger one.")]),
 ("A truck carries 5,000 kg of wheat. Explain how many quintals and tonnes that is.",["100 kg = 1 quintal, so 5,000 / 100 = 50 quintals","1,000 kg = 1 tonne, so 5,000 / 1,000 = 5 tonnes"],["Mixing up quintal (100 kg) and tonne (1,000 kg)"]),
 ["1,000 mg = 1 g; 1,000 g = 1 kg; 100 kg = 1 quintal; 10 quintals = 1 tonne.","Add or subtract like units; regroup when needed.","Word problems: find what is asked, convert to one unit, calculate, convert back, check."],
 [num("r1-wp1",1,"A sugar sachet weighs 5 g. What is its weight in milligrams?",5000,"5 x 1,000 = 5,000 mg.",[(500,"1 g is 1,000 mg, not 100.")],"mg"),
  num("r1-wp2",1,"An ornament weighs 4 g 100 mg. How many milligrams is that?",4100,"4 g = 4,000 mg, plus 100 mg = 4,100 mg.",[(4010,"100 mg must be added fully.")],"mg"),
  num("r1-wp3",1,"How many kg make 1 quintal?",100,"100 kg = 1 quintal.",[(10,"10 quintals make a tonne; 1 quintal is 100 kg.")]),
  num("r1-wp4",1,"How many quintals make 1 tonne?",10,"10 quintals = 1,000 kg = 1 tonne.",[(100,"100 kg is one quintal.")]),
  num("r2-wp5",2,"5,000 kg = ___ tonnes",5,"1,000 kg = 1 tonne, so 5,000 kg = 5 tonnes.",[(50,"50 is the number of quintals.")]),
  num("r2-wp6",2,"9,000 kg = ___ quintals",90,"9,000 / 100 = 90 quintals.",[(9,"9 is the number of tonnes.")]),
  num("r2-wp7",2,"The king donates wheat equal to 10 times his weight. He gives 800 kg. What is his weight in kg?",80,"800 / 10 = 80 kg.",[(8000,"Divide by 10, do not multiply.")],"kg"),
  num("r2-wp8",2,"Last year he gave 780 kg (10 times his weight). How many kg did he gain this year?",2,"Last year 78 kg, this year 80 kg: gain 2 kg.",[(20,"780 / 10 = 78, not 760.")],"kg"),
  short("r2-wp9",2,"2 kg 500 g + 1 kg 750 g = ? (write like 4 kg 250 g)",["4 kg 250 g","4kg 250g","4 kg 250"],"3 kg + 1,250 g = 4 kg 250 g.",[("3 kg 1,250 g","1,250 g makes another kilogram.")]),
  num("r3-wp10",3,"How many grams more is 2 kg 500 g than 1 kg 750 g?",750,"2,500 - 1,750 = 750 g.",[(250,"Check by adding 1,750 + 750 = 2,500.")],"g"),
  mcq("r3-wp11",3,"Which is the heaviest: 5,000 g, 7,500 g or 90 g?","7,500 g",[("5,000 g","5,000 is less than 7,500."),("90 g","90 g is very small.")],"All in grams, 7,500 is largest."),
  tf("r3-wp12",3,"880 mg + 8 mg = 800 mg + 88 mg.",True,"Both give 888 mg.")],
 svg=("c5-weight-unit-ladder.svg","Ladder: 1,000 mg = 1 g, 1,000 g = 1 kg, 100 kg = 1 quintal, 10 quintals = 1 tonne","From tiny to big"))

# ---------- 4 fractions ----------
build(M,'fractions','comparing-and-adding-fractions',"Comparing fractions and fractions greater than 1",
 "Sevi and Shami's chikki",
 "Sevi and Shami share a chikki. Sevi eats 1/3 and Shami eats the rest, 2/3. Who ate more? And when Raman's dad cuts parathas into halves, Maa eats 5 halves - how many parathas is that?",
 [("When the denominators are the same, the pieces are the same size, so the bigger numerator is the bigger fraction. 2/3 is more than 1/3, so Shami ate more.","same denominator"),
  ("Compare 7/8 and 3/8: both are eighths, 7 > 3, so 7/8 > 3/8. Also 3/5 < 4/5 and 5/10 > 3/10.","7/8 > 3/8"),
  ("When the numerators are the same, look at the pieces. 1/5 is bigger than 1/6, because fewer equal parts means bigger pieces. So 4/5 > 4/6 and 3/7 > 3/8.","same numerator"),
  ("Use the fraction kit to check: lay four 1/5 pieces and four 1/6 pieces side by side; the fifths strip is longer.","fraction kit"),
  ("Now fractions greater than 1. Raman's father cuts each paratha into 2 halves. Maa eats 5 pieces of 1/2 = 5/2 parathas.","5/2"),
  ("2 halves make 1 whole. 5 halves = 2 wholes + 1 half = 2 1/2 parathas. On a number line, 5/2 lies halfway between 2 and 3.","2 1/2"),
  ("A fraction whose numerator is greater than its denominator is more than 1. 7/4 = 4/4 + 3/4 = 1 3/4. A number like 2 1/2 with a whole part and a fraction part is a mixed number.","mixed number"),
  ("To compare with 1: if numerator is smaller than the denominator, the fraction is less than 1 (3/4 < 1); if equal it is 1 (4/4); if greater it is more than 1 (5/4 > 1).","compare with 1")],
 ("Maa ate 5 pieces of 1/2 paratha. How many parathas did she eat?",[("5 pieces of 1/2 = 5/2.","Each piece is one half, so five of them make five halves."),("2 halves = 1 paratha, so 4 halves = 2 parathas, with 1 half left: 2 1/2 parathas.","Divide 5 by 2: quotient 2 is the whole part, remainder 1 is the numerator.")]),
 ("Which is greater, 3/7 or 3/8? Explain with a picture in your mind.",["Same numerator, so compare the sizes of pieces","Sevenths are bigger than eighths","So 3/7 > 3/8"],["Thinking a bigger denominator means a bigger fraction"]),
 ["Same denominator: the bigger numerator is bigger.","Same numerator: the smaller denominator is bigger.","Fractions with numerator greater than denominator are more than 1 and can be written as mixed numbers: 5/2 = 2 1/2.","Compare any fraction with 1 using numerator and denominator."],
 [mcq("r1-fc1",1,"Which is greater: 2/3 or 1/3?","2/3",[("1/3","Same denominator; the bigger numerator wins."),("They are equal","2 pieces are more than 1 piece.")],"2 pieces of the same size are more than 1."),
  tf("r1-fc2",1,"7/8 > 3/8",True,"Both are eighths and 7 > 3."),
  mcq("r1-fc3",1,"Which is greater: 4/5 or 4/6?","4/5",[("4/6","Sixths are smaller pieces than fifths."),("Equal","The pieces are different sizes.")],"Same numerator: smaller denominator gives the bigger fraction."),
  num("r1-fc4",1,"How many halves make 3 whole parathas?",6,"Each paratha has 2 halves, so 3 x 2 = 6.",[(3,"3 is the number of wholes.")]),
  mcq("r2-fc5",2,"5/2 as a mixed number is","2 1/2",[("5 1/2","5 is the numerator, not the whole part."),("1 1/2","3/2 is 1 1/2.")],"5 halves = 2 wholes + 1 half."),
  short("r2-fc6",2,"Write 7/4 as a mixed number.",["1 3/4","1 and 3/4"],"7/4 = 4/4 + 3/4 = 1 3/4.",[("3 1/4","Divide 7 by 4: quotient 1, remainder 3.")]),
  mcq("r2-fc7",2,"Which fraction is greater than 1?","5/4",[("3/4","3 < 4, so it is less than 1."),("4/4","4/4 is exactly 1.")],"The numerator 5 is greater than denominator 4."),
  mcq("r2-fc8",2,"Which is greater: 3/8 or 3/7?","3/7",[("3/8","Eighths are smaller than sevenths."),("Equal","Different denominators, different sizes.")],"Same numerator, smaller denominator wins."),
  tf("r3-fc9",3,"6/9 is greater than 6/10.",True,"Ninths are bigger than tenths."),
  tf("r3-fc10",3,"A fraction with a bigger denominator is always bigger.",False,"1/10 < 1/2. A bigger denominator means smaller pieces."),
  num("r3-fc11",3,"3 1/2 parathas = how many halves?",7,"3 wholes = 6 halves, plus 1 half = 7 halves.",[(6,"Do not forget the extra half.")]),
  mcq("r3-fc12",3,"Which is between 1 and 2?","3/2",[("1/2","Less than 1."),("4/2","4/2 = 2.")],"3/2 = 1 1/2.")],
 svg=("c5-fractions-bars.svg","Bars showing 5/2 = 2 1/2 and 4/5 longer than 4/6","Halves, and same numerator comparison"))

# ---------- 5 symmetry lines ----------
build(M,'symmetrical-designs','line-symmetry-and-mirror-images',"Lines of symmetry and alphabet cutouts",
 "Happy Birthday cutouts",
 "Prem and Manu want to paste HAPPY BIRTHDAY letters on the wall for Lali. They notice they do not need to cut each whole letter - folding the paper first is enough!",
 [("A shape has a line of symmetry if folding along the line makes both halves match exactly. This is reflection symmetry.","line of symmetry"),
  ("The letter A has a vertical line of symmetry. To cut it: fold the paper in half, draw half of A along the fold, cut along the outline, and open it to see a full A.","A: vertical"),
  ("The letter H has two lines of symmetry, one vertical and one horizontal. Fold the paper into four (one-fourth), draw one fourth of H, cut and open.","H: two lines"),
  ("Now test the letters E N X T K V O. Horizontal line of symmetry: E, X, K, O. Vertical line: T, X, V, O. Both lines: X and O. N has no line of symmetry.","E N X T K V O"),
  ("Letters with one line need a fold in half (half of the letter). Letters with two lines can be made from one-fourth of the letter.","fold half or quarter"),
  ("Many designs can be made like this: a diya, a boat, a butterfly, a leaf. Fold, draw half, cut, open.","paper cutouts"),
  ("(additional, not in the textbook) A shape can have many lines of symmetry: a square has 4 and a circle has endlessly many.","square 4 lines")],
 ("Which of the letters E, N, X, T have both a vertical and a horizontal line of symmetry?",[("Test each: E has only a horizontal line, T has only a vertical line, N has none.","Fold an imaginary letter both ways."),("X is the same both ways, so X is the answer.","X looks the same after folding along both lines.")]),
 ("Explain how you would cut the letter H from paper using symmetry.",["H has a vertical and a horizontal line","Fold the paper in four","Draw one quarter of H on the folds, cut and open"],["Folding only once for H"]),
 ["Reflection symmetry means the two halves match after a fold.","A has a vertical line; H has two lines.","E, X, K, O have a horizontal line; T, X, V, O have a vertical line; X and O have both.","N has no line of symmetry."],
 [mcq("r1-ls1",1,"Which letter has a vertical line of symmetry?","A",[("N","N changes when folded."),("K","K has a horizontal line only.")],"A's two sides match when folded down the middle."),
  mcq("r1-ls2",1,"How many lines of symmetry does the letter H have?","2",[("1","H has both a vertical and a horizontal line."),("0","H is symmetrical.")],"One vertical and one horizontal line."),
  tf("r1-ls3",1,"To cut out the letter A you fold the paper in half.",True,"A has one vertical line, so one fold is enough."),
  mcq("r2-ls4",2,"Which letter has a horizontal line of symmetry but no vertical line?","E",[("T","T has a vertical line."),("V","V has a vertical line.")],"E's top and bottom halves match."),
  short("r2-ls5",2,"Which two letters out of E N X T K V O have both vertical and horizontal lines?",["x and o","o and x","x, o","o, x","x o","o x"],"Only X and O match both ways.",[("h","H is not in the list.")]),
  mcq("r2-ls6",2,"Which letter has no line of symmetry?","N",[("X","X has two."),("O","O has two.")],"N is not the same after any fold, but it does look the same after a half turn."),
  tf("r2-ls7",2,"The letter T has a horizontal line of symmetry.",False,"T has a vertical line only."),
  num("r3-ls8",3,"How many parts do you fold the paper into to cut a letter with two lines of symmetry (like H)?",4,"Fold once each way, giving four equal parts.",[(2,"Two parts is for a single line of symmetry.")]),
  tf("r3-ls9",3,"The letter V has a vertical line of symmetry.",True,"Folding down the middle matches both arms."),
  mcq("r3-ls10",3,"A square has how many lines of symmetry?","4",[("2","A square also has two diagonal lines."),("1","A square has more than one.")],"2 through the middle of sides and 2 diagonals."),
  tf("r3-ls11",3,"A paper cutout of a diya can be made by folding the paper and cutting half the shape.",True,"The diya has a line of symmetry."),
  mcq("r3-ls12",3,"Which letters have a horizontal line?","E, X, K, O",[("A, T, V","These have vertical lines."),("N only","N has no line.")],"E, X, K, O match top and bottom.")],
 svg=("c5-letter-symmetry.svg","Letters A, H, E and N with their lines of symmetry","Lines of symmetry in letters"))

# ---------- 6 rotational ----------
build(M,'symmetrical-designs','symmetry-around-us',"Rotational symmetry and symmetry in numbers",
 "The windmill that never changes",
 "Lali makes a windmill (firki). When she turns it a quarter, a half, three-quarters or a full turn, it looks exactly the same! This is another kind of symmetry - rotational symmetry.",
 [("A shape has rotational symmetry if it looks the same after turning less than a full turn about its centre.","rotational symmetry"),
  ("A firki looks the same after 1/4, 1/2 and 3/4 turn, and of course after a full turn. A dot on it helps us track the turn.","firki"),
  ("The letter H looks the same after a half turn. So H has rotational symmetry. A also has reflection symmetry, but turned halfway it does not look like A, so it has no rotational symmetry.","H half turn"),
  ("Check letters by cutting them out, fixing the centre with a pin and turning, or by tracing paper. Letters like N, S, X, O and H have rotational symmetry.","N, S, X, O, H"),
  ("Digits: 0, 1, 3, 8 have reflection symmetry. 0 and 8 have rotational symmetry too (1 if written as a plain straight stroke). So 0 and 8 have both.","0 and 8"),
  ("Numbers: 11 and 1001 look the same after a half turn and also have a vertical line, so they have both symmetries. 69 and 96 look the same after a half turn. 88 and 808 have both.","11, 69, 808"),
  ("Try making your own 2-, 3-, 4-digit numbers: 88, 808, 8008 or 69 - check each by turning the page upside down.","own numbers")],
 ("Does the number 69 have rotational symmetry?",[("Turn 69 by a half turn.","A half turn flips the page upside down."),("6 becomes 9 and 9 becomes 6, in swapped places, so it reads 69 again. Yes, 69 has rotational symmetry.","The look is the same after a half turn.")]),
 ("Tell a friend how to test if a shape has rotational symmetry.",["Mark a dot and fix the centre with a pin","Turn it 1/4, 1/2, 3/4","If it looks the same before a full turn, it has rotational symmetry"],["Confusing it with folding for reflection symmetry"]),
 ["Rotational symmetry: looks the same after turning less than a full turn.","Firki: 1/4, 1/2 and 3/4 turns. H: half turn.","Digits 0 and 8 have both reflection and rotational symmetry.","Numbers like 69, 88, 808 and 1001 have rotational symmetry."],
 [mcq("r1-rs1",1,"After how much turn does the letter H look the same?","1/2 turn",[("1/4 turn","H turned a quarter looks like a sideways H."),("No turn","No turn is just the original.")],"A half turn leaves H unchanged."),
  tf("r1-rs2",1,"A firki looks the same after 1/4 turn.",True,"It has four identical blades."),
  tf("r1-rs3",1,"Rotational symmetry needs a fold line.",False,"Rotational symmetry is about turning, not folding."),
  mcq("r2-rs4",2,"Which digit has both reflection and rotational symmetry?","8",[("3","3 has reflection symmetry only."),("2","2 has neither.")],"8 looks the same on folding and after a half turn."),
  tf("r2-rs5",2,"The number 69 looks the same after a half turn.",True,"6 and 9 swap, and 69 reads again."),
  tf("r2-rs6",2,"The number 808 has rotational symmetry.",True,"8 looks the same upside down and 0 too."),
  mcq("r2-rs7",2,"Which letter does NOT have rotational symmetry?","A",[("H","H looks same after half turn."),("X","X also does.")],"A turned half way looks upside down, which is different."),
  short("r3-rs8",3,"Name one letter of the alphabet that looks the same after a half turn but has no line of symmetry.",["n","s","z"],"N, S and Z look the same after a half turn but have no fold line.",[("a","A has a line of symmetry.")]),
  mcq("r3-rs9",3,"How many times does a firki look the same in one full turn?","4",[("2","A firki has four blades."),("1","Only once would mean no symmetry.")],"At 1/4, 1/2, 3/4 and full turn."),
  tf("r3-rs10",3,"A shape with line symmetry always has rotational symmetry.",False,"A has line symmetry only."),
  mcq("r3-rs11",3,"Which number has both vertical line and half-turn symmetry?","88",[("69","69 has rotational but no line symmetry."),("12","12 has neither.")],"Both 8s are symmetric and match."),
  tf("r3-rs12",3,"0 has rotational symmetry.",True,"0 looks the same after a half turn.")],
 svg=("c5-pinwheel-turns.svg","A four-bladed windmill shown after quarter turns","Rotational symmetry of a firki"))

# ---------- 7 making designs ----------
build(M,'symmetrical-designs','making-symmetrical-designs',"Making symmetrical designs: rotation and reflection",
 "Lali's rangoli",
 "Lali draws one small shape and then repeats it by turning and flipping to make a pretty rangoli. Today you become a pattern designer!",
 [("To make a firki: take a square paper, fold diagonally both ways, open it to see an X, cut along the four lines halfway to the centre, fold alternate corners to the centre and pin them. It spins and looks the same after every quarter turn.","firki steps"),
  ("To make a design with half turn symmetry: draw one shape, then draw the same shape again on the opposite side of the centre, rotated a half turn.","half turn design"),
  ("To make a quarter turn design: repeat the shape four times around the centre, each rotated by 1/4 turn.","quarter turn design"),
  ("Check if the design has a line of symmetry: fold it. Some designs have rotational symmetry but no reflection (like a pinwheel with curved blades).","rotation vs reflection"),
  ("To make a pattern with reflection: draw a vertical line and draw the mirror picture on the other side.","mirror design"),
  ("A design looks the same after 1/4 turn only if it can be divided into four identical parts around the centre.","four parts"),
  ("(additional, not in the textbook) Rangoli, kolam and quilt designs use these symmetries.","kolam")],
 ("You have a design with one leaf shape. How can you make it look the same after a half turn?",[("Draw the same leaf on the opposite side of the centre, rotated half turn.","Half turn moves a point to the opposite side."),("Now two leaves face opposite ways and the design looks the same after half a turn.","Check by turning the paper.")]),
 ("How would you make a design that looks the same after 1/4 turn?",["Draw the shape four times","Each copy is turned a quarter turn about the centre","Check by turning the page"],["Drawing only two shapes"]),
 ["Rotational designs repeat a shape around a centre.","1/2 turn symmetry needs 2 identical parts; 1/4 turn needs 4.","Reflection designs repeat a shape as a mirror image."],
 [mcq("r1-md1",1,"How many identical parts does a design need to look the same after every quarter turn?","4",[("2","Two parts give only half turn symmetry."),("3","Three parts are for one-third turns.")],"A quarter is one out of four equal turns."),
  tf("r1-md2",1,"For a firki you cut along the four lines of the X up to the centre.",False,"You stop cutting about halfway to the centre."),
  mcq("r1-md3",1,"What do you see when you open the diagonal folds of the square paper?","an X",[("a plus sign","Diagonal folds make an X."),("a circle","No circle appears.")],"Two diagonal folds cross at the centre."),
  tf("r2-md4",2,"A design with half turn symmetry needs two identical parts around the centre.",True,"Each part moves to the other after half a turn."),
  mcq("r2-md5",2,"To make a mirror design you",'draw the same picture flipped across a line',[("turn the paper","Turning is for rotational symmetry."),("colour it red","Colour is not symmetry.")],"Reflection flips across a line."),
  tf("r2-md6",2,"A shape can have rotational symmetry without a line of symmetry.",True,"A pinwheel with bent blades is an example."),
  num("r2-md7",2,"How many identical parts make a design that matches itself after 1/3 turn?",3,"A third of a turn means 3 equal parts.",[(4,"4 is for quarter turns.")]),
  mcq("r3-md8",3,"Which step comes first in making a firki?","Take a square paper",[("Push a pin","The pin comes last."),("Cut the lines","Cutting follows folding.")],"The square is the starting material."),
  tf("r3-md9",3,"In a firki, the pin goes through the folded corners and the centre.",True,"That lets the firki spin."),
  mcq("r3-md10",3,"Which pattern needs reflection?","a butterfly",[("a spinning windmill","Windmill is rotational."),("a pinwheel","Also rotational.")],"A butterfly's wings are mirror images."),
  tf("r3-md11",3,"The pin should be pushed very tightly.",False,"If too tight, the windmill won't spin."),
  mcq("r3-md12",3,"A design looks the same after a half turn. Which is true?","it has rotational symmetry",[("it must have a fold line","Not always."),("it is not symmetrical","It is symmetrical.")],"Half turn symmetry is a kind of rotational symmetry.")],
 svg=("c5-pinwheel-turns.svg","A four-bladed windmill shown after quarter turns","Windmill designs"))

# ---------- Quilt ----------
build(M,'grandmothers-quilt','perimeter-and-quilt-borders',"Perimeter: the border of a shape",
 "Lace for the quilt",
 "Preetha and Adrit's grandmother made a quilt from old clothes. She wants to decorate its border with lace. Which lace length will cover the entire border - 40 units, 50 units or 25 units?",
 [("The length of the border of a shape is called its perimeter. The lace must be exactly as long as the perimeter.","perimeter"),
  ("The perimeter of a rectangle is length + breadth + length + breadth = 2 x (length + breadth).","2 x (l + b)"),
  ("In a shape with all equal sides, perimeter is the number of sides x one side. For a square of 5 cm: 4 x 5 = 20 cm.","4 x side"),
  ("To choose the lace, find the perimeter first, then pick the lace of exactly that length or use two laces whose lengths add up to it.","choose lace"),
  ("Draw rectangles of perimeter 26 cm: length + breadth = 13, so 8 x 5 or 10 x 3 or 7 x 6. For 18 cm: length + breadth = 9, so 5 x 4 or 6 x 3 or 7 x 2.","drawing rectangles"),
  ("Many rectangles can have the same perimeter, with different shapes.","same perimeter"),
  ("To find the perimeter of any shape, add all its side lengths, or walk along the border.","add all sides")],
 ("Find the perimeter of a rectangle 9 cm long and 4 cm broad.",[("Add: 9 + 4 + 9 + 4 = 26.","Go around the shape adding each side."),("Or 2 x (9 + 4) = 26 cm.","Add length and breadth, double it.")]),
 ("How do you find the perimeter of a square quilt of side 5 units?",["Perimeter is the border length","A square has four equal sides","4 x 5 = 20 units"],["Using side x side (area)"]),
 ["Perimeter is the length of the border.","Rectangle: 2 x (l + b); square: 4 x side.","Different shapes can have the same perimeter."],
 [num("r1-pb1",1,"What is the perimeter of a square of side 5 cm?",20,"4 x 5 = 20 cm.",[(25,"25 is side x side, which is area.")],"cm"),
  num("r1-pb2",1,"A rectangle is 9 cm long and 4 cm broad. Find its perimeter in cm.",26,"9 + 4 + 9 + 4 = 26.",[(36,"36 is the area.")],"cm"),
  mcq("r1-pb3",1,"The length of the border of a shape is its","perimeter",[("area","Area is the space inside."),("height","Height is not the border.")],"Perimeter is the distance around."),
  tf("r1-pb4",1,"Lace for the edge of a quilt must equal its perimeter.",True,"It covers the whole border."),
  num("r2-pb5",2,"Length + breadth of a rectangle with perimeter 26 cm is",13,"Perimeter = 2 x (l + b), so l + b = 13.",[(26,"26 is the whole perimeter.")],"cm"),
  mcq("r2-pb6",2,"Which rectangle has perimeter 18 cm?","5 cm by 4 cm",[("5 cm by 3 cm","Perimeter 16."),("6 cm by 4 cm","Perimeter 20.")],"2 x (5 + 4) = 18."),
  num("r2-pb7",2,"A square rug has side 6 cm. What is its perimeter in cm?",24,"4 x 6 = 24.",[(36,"36 is the area.")],"cm"),
  tf("r2-pb8",2,"Two different rectangles can have the same perimeter.",True,"8 x 5 and 10 x 3 both have perimeter 26."),
  num("r3-pb9",3,"A rectangle has perimeter 50 units and length 15 units. Find its breadth.",10,"l + b = 25, so b = 10.",[(35,"25 - 15 = 10.")],"units"),
  num("r3-pb10",3,"An equilateral triangle has side 7 cm. Perimeter?",21,"3 x 7 = 21 cm.",[(14,"There are three sides, not two.")],"cm"),
  mcq("r3-pb11",3,"Grandmother needs 40 units of lace for the border. Which fits exactly?","Red lace of 40 units",[("Blue lace of 25 units","Too short."),("Green lace of 50 units","Too long, leaving extra.")],"The lace should be equal to the perimeter."),
  tf("r3-pb12",3,"Perimeter is measured in square units.",False,"Perimeter is a length: cm, m; area uses square units.")],
 svg=("c5-area-perimeter.svg","Three rectangles with area 12 and different perimeters","Same area, different perimeter"))

build(M,'grandmothers-quilt','area-by-counting-squares',"Area: covering a region with tiles",
 "Covering the table",
 "Preetha covers her table with triangles and circles, Adrit with squares and rectangles. Whose shapes cover it without gaps? Area is how much surface a shape covers.",
 [("The region covered is called its area. We find area by filling a region with shapes that tile - no gaps and no overlaps - like squares, rectangles and triangles. Circles leave gaps.","tile"),
  ("Table 1 may take some number of triangles, Table 3 some squares and Table 4 some rectangles. The area is that count, in triangle units, square units or rectangle units.","area units"),
  ("To compare areas of rectangles A, B, C, trace and cut them, or place them on a square grid and count the squares.","square grid"),
  ("We choose the square as the standard unit because its sides are equal. The area of a square with side 1 unit is 1 square unit; with side 1 cm it is 1 sq cm.","1 square unit"),
  ("Compare two gardens on a grid by counting the squares each covers. Half squares are counted together to make whole ones.","count squares"),
  ("Trace your palm or a leaf on a square grid and count whole and partly covered squares to estimate its area.","palm and leaf"),
  ("A rug made of square patches: count the patches in one row, then multiply by the rows.","rows x columns")],
 ("A rug has 5 rows with 6 square patches in each row. How many patches does it have?",[("Each row has 6 patches and there are 5 rows.","Equal rows can be multiplied."),("6 x 5 = 30 patches, so its area is 30 square units.","Count of unit squares is the area.")]),
 ("Why do we use a square as a unit of area?",["Square tiles cover without gaps","All sides of a square are equal","1 unit side = 1 square unit area"],["Thinking circles can be used"]),
 ["Area is the surface a shape covers.","Tiles must leave no gaps and no overlaps.","The unit of area is a square unit.","Count squares on a grid to compare areas."],
 [mcq("r1-ac1",1,"Which shape leaves gaps when used to cover a table?","circle",[("square","Squares tile."),("rectangle","Rectangles tile.")],"Circles have round edges and leave gaps."),
  tf("r1-ac2",1,"Squares can cover a table without gaps.",True,"They tile."),
  mcq("r1-ac3",1,"Area means","the surface covered by a shape",[("the border length","That is perimeter."),("the weight","Not related.")],"Area is the inside space."),
  num("r2-ac4",2,"A mat has 4 rows with 7 square patches in each row. How many patches?",28,"4 x 7 = 28.",[(11,"4 + 7 gives 11; use multiplication.")],"patches"),
  mcq("r2-ac5",2,"The area of a square of side 1 cm is","1 square cm",[("1 cm","cm is length."),("4 cm","That is perimeter.")],"Area is in square units."),
  tf("r2-ac6",2,"Overlapping tiles give the correct area.",False,"No overlaps are allowed."),
  num("r2-ac7",2,"A rectangle on a grid covers 3 rows of 5 squares. Its area (square units) is",15,"3 x 5 = 15.",[(8,"Use multiplication.")],"square units"),
  mcq("r3-ac8",3,"Why choose a square as the unit?","all sides are equal",[("it has round edges","Circles do."),("it is red","Colour is irrelevant.")],"Equal sides make measuring easy."),
  tf("r3-ac9",3,"A bigger shape can be compared with a smaller one by counting grid squares.",True,"More squares means larger area."),
  mcq("r3-ac10",3,"To find the area of a leaf, put it on","a square grid",[("a number line","Not for area."),("a clock","No.")],"Count squares."),
  num("r3-ac11",3,"Mat A needs 24 patches and mat B needs 18. How many more for A?",6,"24 - 18 = 6.",[(42,"Subtract, not add.")],"patches"),
  tf("r3-ac12",3,"Two shapes with the same area may look different.",True,"Different arrangements of the same number of squares.")],
 svg=("c5-area-perimeter.svg","Grids showing area 12 for different shapes","Counting squares"))

build(M,'grandmothers-quilt','area-of-rectangles-and-squares',"Area and perimeter together",
 "Trisha's rectangles",
 "Trisha makes two rectangles. She says, I increased the area of my rectangle, and the perimeter increased. Is that always true? We will explore.",
 [("The area of a rectangle = number of squares in one row x number of rows, that is, length x breadth. For a square, side x side.","length x breadth"),
  ("A rectangle 8 cm by 5 cm has area 40 square cm. A square of side 6 cm has area 36 square cm.","8 x 5 = 40"),
  ("Shapes made of 12 squares can be 6 x 2, 4 x 3 or 12 x 1. All have area 12 square units but perimeters 16, 14 and 26 units. So the same area can give different perimeters.","same area"),
  ("Shapes with the same perimeter can have different areas. With perimeter 16: 7 x 1 has area 7, 6 x 2 has 12, 5 x 3 has 15 and 4 x 4 has 16.","same perimeter"),
  ("So is Trisha always right? No. From 12 x 1 (area 12, perimeter 26) to 4 x 4 (area 16, perimeter 16) the area increased but the perimeter decreased.","Trisha is not always right"),
  ("Area and perimeter are different things: area measures the inside in square units and perimeter measures the border in units of length.","area vs perimeter"),
  ("(additional, not in the textbook) For a fixed perimeter, the square gives the biggest area.","square wins")],
 ("Find the area and perimeter of a rectangle 8 cm long and 5 cm broad.",[("Area = 8 x 5 = 40 square cm.","Length x breadth."),("Perimeter = 2 x (8 + 5) = 26 cm.","Add length and breadth and double.")]),
 ("Is it true that when the area of a rectangle increases, its perimeter always increases? Explain with an example.",["Not always","12 x 1 has area 12 and perimeter 26","4 x 4 has area 16 but perimeter 16, which is smaller"],["Believing bigger area means bigger perimeter"]),
 ["Area of a rectangle = length x breadth.","Same area can give different perimeters.","Same perimeter can give different areas.","Area is in square units, perimeter in length units."],
 [num("r1-ar1",1,"Area of a rectangle 8 cm by 5 cm in square cm.",40,"8 x 5 = 40.",[(26,"26 is the perimeter.")],"sq cm"),
  num("r1-ar2",1,"Area of a square of side 6 cm in sq cm.",36,"6 x 6 = 36.",[(24,"24 is the perimeter.")],"sq cm"),
  tf("r1-ar3",1,"Perimeter is measured in square units.",False,"Area uses square units."),
  num("r2-ar4",2,"Perimeter of a rectangle 8 cm by 5 cm in cm.",26,"2 x (8 + 5) = 26.",[(40,"40 is the area.")],"cm"),
  tf("r2-ar5",2,"A 6 x 2 rectangle and a 4 x 3 rectangle have the same area.",True,"Both are 12."),
  tf("r2-ar6",2,"A 6 x 2 rectangle and a 4 x 3 rectangle have the same perimeter.",False,"16 and 14."),
  num("r2-ar7",2,"A garden is 12 m long and 1 m wide. Perimeter in m?",26,"2 x (12 + 1) = 26.",[(12,"12 is the area.")],"m"),
  mcq("r3-ar8",3,"Which has the greatest area with perimeter 16: 7 x 1, 6 x 2, 5 x 3, 4 x 4?","4 x 4",[("7 x 1","Area 7."),("6 x 2","Area 12.")],"Area 16."),
  tf("r3-ar9",3,"If area increases, perimeter must increase.",False,"12x1 to 4x4: area up, perimeter down."),
  num("r3-ar10",3,"A rectangular floor is 7 m by 4 m. How many square tiles of 1 sq m are needed?",28,"7 x 4 = 28.",[(22,"22 is the perimeter.")],"tiles"),
  mcq("r3-ar11",3,"Two shapes with equal area",'may have different perimeters',[("always have the same perimeter","6x2 and 12x1 differ."),("cannot exist","They do.")],"Area and perimeter are separate."),
  num("r3-ar12",3,"The area of a rectangle is 24 sq units and its length is 6 units. What is its breadth?",4,"24 / 6 = 4.",[(18,"Divide, not subtract.")],"units")],
 svg=("c5-area-perimeter.svg","Rectangles with equal area and different perimeters","Area vs perimeter"))

# ---------- maps grid ----------
build(M,'maps-and-locations','grids-and-finding-locations',"Grids: finding places on a map",
 "Where is the park?",
 "Your friend says: meet me at the park. But on a big map, how will you tell exactly where? A grid of letters and numbers works like an address.",
 [("A map is divided into rows and columns by a grid. Columns are named with letters (A, B, C...) and rows with numbers (1, 2, 3...).","grid"),
  ("To locate a place, give the column letter first and then the row number, like C3.","C3"),
  ("On our sample map the school is at A1, the park at C3 and the well at E5.","school A1"),
  ("To find a place: go along to the column letter, go down to the row number, and the square where they meet is the place.","meet"),
  ("Two places in the same row have the same number: A1 and E1. Places in the same column have the same letter: C1 and C3.","same row"),
  ("Always check which comes first on your map: here column letter, then row number.","order matters"),
  ("(additional, not in the textbook) The same idea is used in chess boards, spreadsheets and the index of a road atlas.","other uses")],
 ("Which square is two columns to the right and two rows down from A1?",[("Moving two columns from A gives C.","A, B, C."),("Two rows down from 1 gives 3, so C3 - where the park is.","1, 2, 3.")]),
 ("How do you describe a place on a grid map?",["Columns have letters","Rows have numbers","Say column letter then row number, like C3"],["Swapping the order of letter and number"]),
 ["Grid maps use letters for columns and numbers for rows.","A location is given as letter then number, like C3.","Places in the same row share the number."],
 [mcq("r1-gm1",1,"On the sample grid, where is the park?","C3",[("3C","Say the column letter first."),("A1","That is the school.")],"Column C, row 3."),
  mcq("r1-gm2",1,"On the sample grid, the school is at","A1",[("E5","That is the well."),("C3","The park.")],"Column A, row 1."),
  tf("r1-gm3",1,"Rows are numbered and columns have letters on the sample map.",True,"That is how it is drawn."),
  short("r2-gm4",2,"Where is the well on the sample grid?",["e5","E5"],"Column E, row 5.",[("5e","Write letter first.")]),
  mcq("r2-gm5",2,"Which two places are in the same row?","A1 and E1",[("A1 and A5","Same column."),("C3 and E5","Different row and column.")],"Row number 1 is shared."),
  mcq("r2-gm6",2,"Which two places are in the same column?","C1 and C3",[("A1 and B1","Same row."),("D2 and E2","Same row.")],"Column letter C is shared."),
  tf("r3-gm7",3,"B4 means column B, row 4.",True,"Letter first, number second."),
  mcq("r3-gm8",3,"Moving from A1 two columns right and two rows down brings you to","C3",[("B2","That is only one step."),("A3","That is only down.")],"A to C and 1 to 3."),
  num("r3-gm9",3,"A grid has 5 columns and 5 rows. How many squares does it have?",25,"5 x 5 = 25.",[(10,"Multiply rows and columns.")]),
  tf("r3-gm10",3,"Two different places can have the same grid reference.",False,"Each reference names one square (but a square may contain several places)."),
  mcq("r3-gm11",3,"To locate a place you first",'find the column letter',[("find the row number","Letter comes first here."),("guess","Use the grid.")],"Go along then down."),
  tf("r3-gm12",3,"A map grid helps give exact addresses.",True,"That is its purpose.")],
 svg=("c5-map-grid.svg","A 5 by 5 map grid with school at A1, park at C3 and well at E5","Grid map"))
print("built")
